glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
#ifdef GL_FRAGMENT_PRECISION_HIGH
  precision highp float;
#else
  precision mediump float;
#endif
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform sampler2D noiseTex0;
uniform sampler2D noiseTex1;
uniform sampler2D noiseTex2;
uniform sampler2D noiseTex3;
uniform sampler2D noiseTex4;
uniform sampler2D sparkleTex;
uniform UBO_FS {
  vec4 sparkleGridXY;
  float sparkleIntensity;
  float noisePow;
  float noiseMul;
  float noiseScl;
  float frameDuration;
  float sparkleSpeedMul;
};
vec3 sampleNoise(float texIdx, vec2 nuv) {
  if (texIdx < 0.5) return texture2D(noiseTex0, nuv).rgb;
  if (texIdx < 1.5) return texture2D(noiseTex1, nuv).rgb;
  if (texIdx < 2.5) return texture2D(noiseTex2, nuv).rgb;
  if (texIdx < 3.5) return texture2D(noiseTex3, nuv).rgb;
  return texture2D(noiseTex4, nuv).rgb;
}
vec3 channelMask(float chIdx) {
  if (chIdx < 0.5) return vec3(1.0, 0.0, 0.0);
  if (chIdx < 1.5) return vec3(0.0, 1.0, 0.0);
  return vec3(0.0, 0.0, 1.0);
}
float sampleNoiseFrame(float frameIdx, vec2 nuv) {
  float texIdx = floor(frameIdx / 3.0);
  float chIdx  = frameIdx - texIdx * 3.0;
  return max(dot(sampleNoise(texIdx, nuv), channelMask(chIdx)), 1e-6);
}
void main () {
  #if USE_TEXTURE
  vec4 baseColor = texture2D(texture, v_uv0);
  if (baseColor.a < 0.01) {
    discard;
  }
  float PERIOD = 26.0;
  float pp = 13.0 - abs(mod(cc_time.x / frameDuration, PERIOD) - 13.0);
  float fA = clamp(floor(pp), 0.0, 13.0);
  float fB = clamp(ceil(pp), 0.0, 13.0);
  float noiseLerp = fract(pp);
  vec2 nuv = fract(v_uv0 * noiseScl);
  float s1 = sampleNoiseFrame(fA, nuv);
  float noiseVal = exp2(log2(s1) * noisePow) * noiseMul;
  if (noiseLerp > 1e-3) {
    float s2 = sampleNoiseFrame(fB, nuv);
    float nv2 = exp2(log2(s2) * noisePow) * noiseMul;
    noiseVal = mix(noiseVal, nv2, noiseLerp);
  }
  vec3 result = clamp(baseColor.rgb + vec3(noiseVal), 0.0, 1.0);
  vec4 o = vec4(result, baseColor.a);
  o *= v_color;
  ALPHA_TEST(o);
  gl_FragColor = o;
  #else
  gl_FragColor = v_color;
  #endif
}

